// The 24px gear glyph is drawn larger within its box than the rest of the icon
// set (~18 vs ~13.5 units). It's centered at (12, 12), so widening its viewBox
// renders it at the set's optical size without touching the path or callers.
const viewBoxes = {
  16: '0 0 16 16',
  24: '-4 -4 32 32',
}

export const GearIcon: React.FC<{
  readonly ariaLabel?: string
  readonly className?: string
  readonly size?: 16 | 24
}> = ({ ariaLabel, className, size = 24 }) => (
  <svg
    aria-label={ariaLabel}
    className={['icon', 'icon--gear', className].filter(Boolean).join(' ')}
    fill="none"
    height={size}
    viewBox={viewBoxes[size]}
    width={size}
    xmlns="http://www.w3.org/2000/svg"
  >
    <path clipRule="evenodd" d={paths[size]} fill="currentColor" fillRule="evenodd" />
  </svg>
)
